27	// isTraceReady is the "ready" state of the plan (target known, nothing sent):
28	// neither running, nor finished, nor the tab's editing state.
29	func isTraceReady(pm *PathModel) bool {
30		return !pm.running() && pm.state != pathDone && pm.state != pathEditing
31	}
