33	// routeLevel returns results over host with the cursor on the Local route row,
34	// after H. The engine resolves to a fixed address.
35	func routeLevel(t *testing.T, host string) (*Model, *fakeEngine) {
36		t.Helper()
37		m, fe := routeResults(t, host)
38		fe.resolveFn = func(context.Context, string) ([]netip.Addr, error) {
39			return []netip.Addr{netip.MustParseAddr("93.184.216.34")}, nil
40		}
41		m = selectCheck(t, m, netcheck.CheckRoute)
42		m = feed(t, m, testutil.Key(keymap.Diagnose))
43		if m.state != StateTrace || m.activeTab != tabDiagnostics {
44			t.Fatalf("H left state=%v tab=%d, want StateTrace on the Diagnostics tab", m.state, m.activeTab)
45		}
46		return m, fe
47	}
