49	func TestHOnTheRouteRowOpensTheTraceLevelWithoutTracing(t *testing.T) {
50		m, fe := routeResults(t, "example.com")
51		m = selectCheck(t, m, netcheck.CheckRoute)
52		gen := m.pathModel.gen
53	
54		m, cmd := step(t, m, testutil.Key(keymap.Diagnose))
55	
56		if m.state != StateTrace || m.activeTab != tabDiagnostics {
57			t.Fatalf("state=%v tab=%d, want StateTrace on the Diagnostics tab", m.state, m.activeTab)
58		}
59		pm := m.pathModel
60		if !isTraceReady(pm) {
61			t.Errorf("Path state = %v, want the ready state (nothing sent)", pm.state)
62		}
63		if pm.target.Host != "example.com" {
64			t.Errorf("target = %q, want the results' host", pm.target.Host)
65		}
66		if pm.gen != gen || pm.running() {
67			t.Errorf("gen %d->%d running=%v, want no run started", gen, pm.gen, pm.running())
68		}
69		_ = testutil.Msgs(cmd)
70		if fe.resolveCalls != 0 || fe.traceCalls != 0 {
71			t.Errorf("engine called (resolve %d, trace %d); H must send nothing", fe.resolveCalls, fe.traceCalls)
72		}
73		title := ansi.Strip(m.GetTitle())
74		if !strings.Contains(title, "Path") || !strings.Contains(title, "example.com") {
75			t.Errorf("title = %q, want Network > Path > example.com", title)
76		}
77		if _, ok := headerValue(pm, "Target"); !ok {
78			t.Error("no Target in the sub-level header")
79		}
80	}
