387	// A failed run stays in the sub-level with its error, and enter retries.
388	func TestTraceLevelAFailedRunStaysInTheSubLevelWithItsError(t *testing.T) {
389		m, _, _ := traceLevelModel(t, traceLevelHost)
390		m = feed(t, m, pathDoneMsg{gen: m.pathModel.gen, err: context.DeadlineExceeded})
