// Interfaces: the search bar stays joined while the body is trimmed.
func TestInterfacesSearchBarStaysJoinedWhileTheBodyIsTrimmed(t *testing.T) {
	seen := 0
	for h := 12; h <= 24; h++ {
		a := netdiagApp(t, 120, h)
		feedView(a, testutil.Keys("tab", "tab")...)
		feedView(a, testutil.Key("/"))

		lines := screen(a)
		assertBarAttached(t, lines, h)
		i := lineIndex(lines, "│ /")
		if i < 0 {
			continue
		}
		if isBox(lines[i-1], "┌", "┐") {
			continue // the body is cut entirely: the documented floor
		}
		seen++
		if !isBox(lines[i-1], "├", "┤") {
			t.Errorf("height %d: the line above the bar is %q, want ├…┤", h, lines[i-1])
		}
	}
	if seen == 0 {
		t.Fatal("the Interfaces bar was never on screen in the heights tried")
	}
}
